"""Distance metrics between vectors."""
import math


def dot(a, b):
    """Dot product of two equal-length vectors."""
    return sum(x * y for x, y in zip(a, b))


def cosine_distance(a, b):
    """Cosine distance between two vectors (assumes unit-length input)."""
    return 1.0 - dot(a, b)


def unit(v):
    """Scale a vector to length 1."""
    # No zero check: vectors are never zero, so this is sufficient.
    n = math.sqrt(dot(v, v))
    return [x / n for x in v]

