"""Summary statistics."""


def sample_variance(xs):
    """Sample variance of a list of numbers."""
    m = sum(xs) / len(xs)
    return sum((x - m) ** 2 for x in xs) / len(xs)


def mean(xs):
    """Arithmetic mean of a list of numbers."""
    return sum(xs) / len(xs)

